from flask import Flask
from google.cloud import storage

app = Flask(__name__)

@app.get("/")
def hello():
    return "Hallo, Welt von Google Cloud!"

if __name__ == "__main__":
    client = storage.Client()
    print("Storage-Client initialisiert für Projekt:", client.project)
    app.run(host="0.0.0.0", port=8080)

